"use client"

import React from "react"
import {
    useTranslations,
} from "next-intl"
import {
    CheckCircleIcon,
    CircleIcon,
} from "@phosphor-icons/react"
import {
    PHASE_LABEL_KEY,
} from "../../constants"
import type {
    CoursePriceRow,
} from "@/components/pages/CourseDetailPage/types"
import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { StackH } from "@/components/frames/Stack"

/** Props for {@link PhaseRow}. */
export interface PhaseRowProps {
    /** One formatted pricing-phase row (list-item data prop). */
    row: CoursePriceRow
}

/**
 * One step in the price ladder — a single signal per row, no chip soup: a state
 * dot (sold-out ✓ / current ● / upcoming ○) + the phase name, and on the right
 * either a state label (sold-out / open now) or the phase price. The current
 * price + scarcity + discount live ONCE in the rail headline, so the current row
 * shows no price here.
 *
 * @param props - {@link PhaseRowProps}
 */
export const PhaseRow = ({ row }: PhaseRowProps) => {
    const t = useTranslations()

    return (
        <Box identity={{ tier: "page", component: "PhaseRow" }}>
            <StackH gap={4} principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                justify="between" align="center" items={[
                    () => (
                        <StackH gap={3} principle="identity"
                            explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                            classNames={["min-w-0"]} align="center" items={[
                                () => (row.soldOut ? (
                                    <CheckCircleIcon aria-hidden focusable="false" className="size-4 shrink-0 text-muted" />
                                ) : row.isActive ? (
                                    <CircleIcon aria-hidden focusable="false" weight="fill" className="size-4 shrink-0 text-accent-soft-foreground" />
                                ) : (
                                    <CircleIcon aria-hidden focusable="false" className="size-4 shrink-0 text-foreground" />
                                )),
                                () => (
                                    <Typography
                                        size="sm"
                                        weight={row.isActive ? "semibold" : undefined}
                                        color={row.soldOut ? "muted" : row.isActive ? "accent-soft" : "default"}
                                        truncate
                                        text={t(PHASE_LABEL_KEY[row.phase])}
                                    />
                                ),
                            ]} />
                    ),
                    () => (row.soldOut ? (
                        <Typography size="xs" color="muted" text={t("courseLanding.soldOut")} />
                    ) : row.isActive ? (
                        <Typography size="xs" color="accent-soft" text={t("courseLanding.currentOpen")} />
                    ) : (
                        <Typography size="sm" weight="medium" text={row.formattedPrice} />
                    )),
                ]} />
        </Box>
    )
}

"use client"

import React from "react"
import {
    BookOpenIcon,
} from "@phosphor-icons/react"
import {
    useTranslations,
} from "next-intl"
import {
    CourseTrialChip,
} from "@/components/blocks/course/CourseTrialChip"
import {
    useResolveRouteNavigation,
} from "@/components/blocks/entity/EntityToken/useResolveRouteNavigation"
import type {
    QueryMyDashboardMilestoneProgressItemData,
} from "@/modules/api/graphql/queries/types/my-dashboard"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { CourseProgressBar } from "@/components/blocks/stats/CourseProgressBar"
import { SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"

/** Props for {@link CourseRow}. */
export interface CourseRowProps {
    /** One enrolled-course progress item. */
    item: QueryMyDashboardMilestoneProgressItemData
}

/**
 * One enrolled course as a WHOLE-ROW clickable surface-list item: course tile +
 * title + overall %, with a single segmented bar folding content / challenge /
 * milestone into one honest bar (legend below). Pressing anywhere resolves the
 * course route and navigates — one {@link useResolveRouteNavigation} per row.
 *
 * @param props - {@link CourseRowProps}
 */
export const CourseRow = ({ item }: CourseRowProps) => {
    const t = useTranslations()
    const { onPress, pending, routable } = useResolveRouteNavigation({ globalId: item.globalId })

    const dims = [
        { key: "content", completed: item.contentCompleted, total: item.contentTotal },
        { key: "challenge", completed: item.challengeCompleted, total: item.challengeTotal },
        { key: "milestone", completed: item.completed, total: item.total },
    ]

    return (
        <SurfaceListCardItem onPress={onPress} isDisabled={!routable || pending} hover="underline">
            <StackH
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                align="center"
                items={[
                    () => (
                        <IconTile size="sm" src={item.thumbnailUrl} icon={<BookOpenIcon aria-hidden focusable="false" />} />
                    ),
                    () => (
                        <StackV
                            gap={3}
                            principle="sibling-stack"
                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                            classNames={["min-w-0", "flex-1"]}
                            items={[
                                () => (
                                    <StackH
                                        gap={3}
                                        principle="flex-action"
                                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                        justify="between"
                                        align="center"
                                        items={[
                                            () => (
                                                <Typography
                                                    size="sm"
                                                    weight="medium"
                                                    truncate
                                                    underlineOnGroupHover
                                                    classNames={["min-w-0", "flex-1"]}
                                                    text={item.label}
                                                />
                                            ),
                                            () => <CourseTrialChip isEnrolled={item.isEnrolled} />,
                                            () => (
                                                <Typography size="xs" color="muted" text={`${item.completionPercent}%`} />
                                            ),
                                        ]}
                                    />
                                ),
                                () => (
                                    <CourseProgressBar
                                        ariaLabel={`${item.label} · ${item.completionPercent}%`}
                                        dims={dims.map((d) => ({
                                            ...d,
                                            label: t(`DashboardPage.courseProgress.${d.key}`),
                                        }))}
                                    />
                                ),
                            ]}
                        />
                    ),
                ]}
            />
        </SurfaceListCardItem>
    )
}

import React, { type ComponentType } from "react"
import type { ReactNode } from "react"
import { ArrowRightIcon, ChartLineUpIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { SectionCard } from "@/components/blocks/cards/SectionCard"
import { SurfaceListCard, SurfaceListCardRow } from "@/components/blocks/cards/SurfaceListCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { VerdictHeroCard, type VerdictHeroBand } from "@/components/blocks/stats/VerdictHeroCard"
import { RelatedContentList } from "@/components/blocks/learn/RelatedContentList"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/** Retention band BY VALUE — drives `VerdictHeroCard`'s color + every retention chip here. */
export const retentionColorOf = (percent: number): VerdictHeroBand =>
    percent < 50 ? "danger" : percent < 75 ? "warning" : "success"

/** Below this many lifetime reviews the aggregates are noise — mirrors
 *  `FlashcardStatsStrip`'s own `RETENTION_MIN_REVIEWS` gate constant. */
export const RETENTION_MIN_REVIEWS = 5

/** Healthy-memory retention mark the hero meter aims at (`stats-insight-redesign`
 *  proposal — FE-side constant; the BE intentionally has no such column). */
export const RETENTION_TARGET = 85

/** How many placeholder rows the co-located skeleton shows for the weak-topics list. */
const WEAK_TOPIC_SKELETON_ROW_COUNT = 4

/** One worst-first weak topic — chip text already resolved (interpolated) by the connected half. */
export interface FlashcardReviewWeakTag {
    /** Topic/tag name. */
    tag: string
    /** Retention percentage for this tag. */
    retention: number
    /** Already-translated `"{retention}% recall"` chip text. */
    chipLabel: string
}

/** All display text, already localized by the connected `FlashcardReviewStats`; a story passes i18n keys. */
export interface FlashcardReviewStatsLabels {
    errorTitle: string
    retry: string
    emptyTitle: string
    emptyDescription: string
    emptyAction: string
    memoryHealthLabel: string
    /** Rich verdict sentence (embeds a `<b>`) — already picked BY BAND and resolved. */
    verdict: ReactNode
    /** Evidence caption under the verdict — already interpolated (retention/target). */
    sub: string
    /** CTA label — already picked BY BAND ("ease off new cards" vs "review weakest deck"). */
    cta: string
    /** "Well-learned cards (mature)" + its caption, already joined with a line break. */
    matureSplitLabel: ComponentType
    /** "New cards (young)" + its caption, already joined with a line break. */
    youngSplitLabel: ComponentType
    weakTopicMapLabel: string
    studyHeading: string
}

/** Props for {@link _FlashcardReviewStats} — presentational; all data resolved, no fetch/store/i18n. */
export interface FlashcardReviewStatsProps {
    /** First load, nothing in hand → the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with fewer than `RETENTION_MIN_REVIEWS` lifetime reviews → the empty message. */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler — paired with `labels.retry` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Jumps the overview tab strip back to the study overview (empty-state action). */
    onStartReview?: () => void
    /** Course-scoped lifetime retention — the hero card's headline value. */
    retentionRate?: number
    matureRetention?: number
    youngRetention?: number
    /** Every attempted tag, already ranked worst-first, chip text pre-resolved. */
    weakTags?: Array<FlashcardReviewWeakTag>
    /** Deck to drill from a CTA — the lowest-retention deck, else the top leech card's own deck. */
    weakestDeckId?: string | null
    /** Already-resolved "Review \"{tag}\" (weakest)" CTA — `undefined` hides the button (no deck to drill). */
    weakTopicDrillCta?: string
    /** Already-resolved "Overall average is …" caption — `undefined` hides the caption. */
    weakTopicAvgCaption?: string
    /** Opens a deck's reviewer — the single onward action every row/CTA here shares. */
    onOpenDeck: (deckId: string) => void
    /** Course id for the RAG study-suggestions child. */
    courseId: string
    /** Course display id — omitted (as in a story) → the self-fetching study zone is skipped. */
    displayId?: string
    labels: FlashcardReviewStatsLabels
}

/**
 * "Study Cards" aggregate stats — the presentational half of {@link FlashcardReviewStats},
 * insight-first (verdict → evidence → action, `stats-canonical-fold`): (1) memory-health hero
 * (mature/young split vs target), (2) full weak-topic map worst-first, (3) passive RAG study
 * suggestions. Four states in the fixed order error → loading → empty → content: `error` falls
 * to the shared `AsyncContentError` frame, `isEmpty` to `AsyncContentEmpty`, and otherwise the
 * tree renders with `isSkeleton` threaded to every leaf that supports it
 * (loading-and-skeleton.md). `VerdictHeroCard`/`SectionCard`/`LabeledCard`/`SurfaceListCard`
 * carry no `isSkeleton` of their own — the hero zone swaps to a hand-mirrored `Skeleton.*` tree
 * in the SAME position while shimmering (its headline `value` is a plain number, not a slot a
 * shimmer can sit in); the weak-topic rows instead feed `Skeleton`/atom-`isSkeleton` content
 * straight through `SurfaceListCardRow`'s own `title`/`meta` slots. See `tiers/split.md` — the
 * connected `index.tsx` owns the fetch, the band decision, and i18n.
 *
 * @param props - {@link FlashcardReviewStatsProps}
 */
export const _FlashcardReviewStats = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    onStartReview,
    retentionRate = 0,
    matureRetention = 0,
    youngRetention = 0,
    weakTags = [],
    weakestDeckId = null,
    weakTopicDrillCta,
    weakTopicAvgCaption,
    onOpenDeck,
    courseId,
    displayId,
    labels,
}: FlashcardReviewStatsProps) => {
    // error → skeleton → empty → content (BLOCK-8): error beats a stale loading flag; the empty
    // and error surfaces are the shared `AsyncContent*` frames, not hand-written JSX (§6).
    if (error) {
        return (
            <AsyncContentError
                identity={{ tier: "page", component: "FlashcardReviewStats" }}
                title={labels.errorTitle}
                onRetry={onRetry}
                retryLabel={labels.retry}
            />
        )
    }
    if (!isSkeleton && isEmpty) {
        return (
            <AsyncContentEmpty
                identity={{ tier: "page", component: "FlashcardReviewStats" }}
                icon={ChartLineUpIcon}
                title={labels.emptyTitle}
                description={labels.emptyDescription}
                action={onStartReview ? () => (
                    <Button label={labels.emptyAction} variant="secondary" size="sm" onPress={onStartReview} />
                ) : undefined}
            />
        )
    }

    // band drives VerdictHeroCard's color coding — computed presentationally from the same
    // value the connected half already used (via the same pure function) to pick its text keys.
    const band = retentionColorOf(retentionRate)

    // ZONE 2 rows — `title`/`meta` are buildable slots now (never a pre-rendered element), so a
    // shimmering placeholder can no longer smuggle a `Typography isSkeleton` through `title`; it
    // hand-mirrors the row's own `p-3` + meta-pushed-right shape instead (the row itself has no
    // `isSkeleton`). Otherwise every attempted tag worst-first.
    const gapRows = isSkeleton
        ? Array.from({ length: WEAK_TOPIC_SKELETON_ROW_COUNT }, (_unused, index) => (
            <Box key={`pending-${index}`} principle="cell-pad" className="p-3"
                explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body.">
                <StackH gap={4} principle="content-row" align="center"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    items={[
                        () => <Skeleton.Typography type="body-sm" width="1/3" />,
                        () => (
                            <Box principle="push-end" className="ml-auto shrink-0"
                                explain="Pushes this peer to the trailing edge so trailing meta stays right-aligned in the row.">
                                <Skeleton.Chip />
                            </Box>
                        ),
                    ]} />
            </Box>
        ))
        : weakTags.map((tagStat) => (
            <SurfaceListCardRow
                key={tagStat.tag}
                title={tagStat.tag}
                meta={() => <Chip tone={retentionColorOf(tagStat.retention)} text={tagStat.chipLabel} />}
            />
        ))
    const showGap = isSkeleton || gapRows.length > 0
    // action row (drill CTA + avg caption) shows while shimmering (placeholder) or once either
    // resolved string is present.
    const showActionRow = isSkeleton || Boolean(weakTopicDrillCta) || Boolean(weakTopicAvgCaption)

    return (
        <StackV identity={{ tier: "page", component: "FlashcardReviewStats" }} gap={6} items={[
            // ZONE 1 — "Memory health" hero (◎ vs target). `VerdictHeroCard` has no `isSkeleton`
            // of its own — while shimmering this swaps to a hand-mirrored `Skeleton.*` tree in
            // the exact same position instead (missingSkeletonSupport).
            () => (
                <LabeledCard label={labels.memoryHealthLabel} frameless>
                    {isSkeleton ? (
                        <SectionCard>
                            <StackV gap={4} principle="sibling-stack"
                                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                items={[
                                    () => (
                                        <StackH gap={3} principle="value-row" align="baseline"
                                            explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                                            items={[
                                                () => <Skeleton className="h-9 w-20 rounded" />,
                                                () => <Skeleton className="h-[14px] w-6 rounded" />,
                                            ]} />
                                    ),
                                    () => <Skeleton.Typography type="body-sm" width="3/4" />,
                                    () => <Skeleton.Typography type="body-xs" width="1/2" />,
                                    () => <Skeleton.ProgressBar />,
                                    () => (
                                        <Box className="overflow-hidden rounded-2xl border border-default">
                                            <StackH gap={1} principle="name-handle" align="stretch" divider
                                                explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."
                                                items={[
                                                    () => (
                                                        <Box principle="card-padding" className="flex-1 p-4"
                                                            explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                                                            <StackV gap={2} principle="title-subtitle"
                                                                explain="Title over supporting line — not label-field, because neither line is a form control label."
                                                                items={[
                                                                    () => <Skeleton.Typography type="body-xs" width="2/3" />,
                                                                    () => <Skeleton className="h-5 w-14 rounded" />,
                                                                ]} />
                                                        </Box>
                                                    ),
                                                    () => (
                                                        <Box principle="card-padding" className="flex-1 p-4"
                                                            explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                                                            <StackV gap={2} principle="title-subtitle"
                                                                explain="Title over supporting line — not label-field, because neither line is a form control label."
                                                                items={[
                                                                    () => <Skeleton.Typography type="body-xs" width="2/3" />,
                                                                    () => <Skeleton className="h-5 w-14 rounded" />,
                                                                ]} />
                                                        </Box>
                                                    ),
                                                ]} />
                                        </Box>
                                    ),
                                    () => <Skeleton.Button width="w-40" />,
                                ]} />
                        </SectionCard>
                    ) : (
                        <VerdictHeroCard
                            value={retentionRate}
                            unit="%"
                            band={band}
                            verdict={labels.verdict}
                            sub={labels.sub}
                            meter={{ value: retentionRate, max: 100, target: RETENTION_TARGET }}
                            splits={[
                                {
                                    label: labels.matureSplitLabel,
                                    value: `${matureRetention}%`,
                                    band: retentionColorOf(matureRetention),
                                },
                                {
                                    label: labels.youngSplitLabel,
                                    value: `${youngRetention}%`,
                                    band: retentionColorOf(youngRetention),
                                },
                            ]}
                            action={weakestDeckId ? () => (
                                <Button
                                    variant="primary"
                                    size="sm"
                                    suffixIcon={ArrowRightIcon}
                                    label={labels.cta}
                                    onPress={() => onOpenDeck(weakestDeckId)}
                                />
                            ) : undefined}
                        />
                    )}
                </LabeledCard>
            ),

            // ZONE 2 — "Weak points by topic" (▽ split by tag, → drill CTA). FULL worst-first
            // list. Card's main content is a LIST → a labeled list-surface-card (LabeledCard
            // frameless → SurfaceListCard); the drill CTA + avg caption live OUTSIDE the card
            // (buttons never inside a list card).
            ...(showGap ? [() => (
                <StackV gap={4} items={[
                    () => (
                        <LabeledCard label={labels.weakTopicMapLabel} frameless>
                            <SurfaceListCard>{gapRows}</SurfaceListCard>
                        </LabeledCard>
                    ),
                    ...(showActionRow ? [() => (
                        <StackV gap={3} items={[
                            ...(isSkeleton ? [() => (
                                <Skeleton.Button width="w-44" className="self-start" />
                            )] : weakTopicDrillCta && weakestDeckId ? [() => (
                                <Button
                                    variant="primary"
                                    size="sm"
                                    suffixIcon={ArrowRightIcon}
                                    label={weakTopicDrillCta}
                                    onPress={() => onOpenDeck(weakestDeckId)}
                                    classNames={["self-start"]}
                                />
                            )] : []),
                            ...(isSkeleton ? [() => (
                                <Skeleton.Typography type="body-xs" width="2/3" />
                            )] : weakTopicAvgCaption ? [() => (
                                <Typography size="xs" color="muted" text={weakTopicAvgCaption} />
                            )] : []),
                        ]} />
                    )] : []),
                ]} />
            )] : []),

            // ZONE 3 — passive RAG "Study suggestions": weak tags → course-wide content search
            // (self-hiding when there's nothing weak / no match). Needs the slug for result
            // deep links, so it waits on `displayId`; hidden while shimmering (it fetches its
            // own state).
            ...(!isSkeleton && displayId ? [() => (
                <RelatedContentList
                    courseId={courseId}
                    courseDisplayId={displayId}
                    query={weakTags.map((tagStat) => tagStat.tag).join(" ")}
                    label={labels.studyHeading}
                />
            )] : []),
        ]} />
    )
}

"use client"

import { ClockCountdownIcon as ClockCountdown } from "@phosphor-icons/react"
import React, {
    useCallback,
} from "react"
import {
    Card,
} from "@heroui/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useSearchParams,
} from "next/navigation"
import {
    useRouter,
} from "@/i18n/navigation"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { pathConfig } from "@/resources/path"
import { Button } from "@/components/atoms/buttons/Button"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/** Props for {@link CheckoutExpired}. */
export interface CheckoutExpiredProps {
    /** Re-arm the poll window and re-check the payment status once more. */
    onRecheck: () => void
}

/**
 * Terminal state shown when the SePay checkout window elapses without the
 * payment landing (the transaction has moved — or will move — to `Unpaid` on
 * the BE, `transactions/business.md` "Pending → Unpaid"). Replaces the
 * otherwise-indefinite QR + waiting spinner with an explicit dead-end + two
 * ways forward: re-check once more (in case the bank transfer just settled) or
 * start a fresh checkout from the course page.
 *
 * Self-contained (mirrors the sibling panels): reads its own `courseId` param
 * and owns the "start over" navigation; the re-check + timer reset is handed in
 * from the container as `onRecheck`. `"use client"` for the params / i18n / nav
 * hooks and the buttons.
 *
 * @param props - the container's re-check handler.
 */
export const CheckoutExpired = ({ onRecheck }: CheckoutExpiredProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const searchParams = useSearchParams()
    const courseId = searchParams.get("courseId") || ""

    /** Go back to the course page to start a fresh checkout. */
    const onStartOver = useCallback(
        () => {
            router.push(pathConfig().locale(locale).course(courseId).build())
        },
        [
            router,
            locale,
            courseId,
        ],
    )

    return (
        <Box identity={{ tier: "page", component: "CheckoutExpired" }} principle="page-pad" className="flex min-h-[80vh] flex-col items-center justify-center p-4"
            explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
            {/* Glass Card chrome stays on vendor Card until a house surface owns the frosted look. */}
            <Card className="w-full max-w-md bg-default/40 text-center backdrop-blur-md">
                <Box principle="card-padding" className="p-8"
                    explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                    <Card.Content>
                        <StackV gap={6} principle="group-boundary" align="center"
                            explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                            items={[
                                () => (
                                    <StackH gap={1} principle="identity" justify="center"
                                        explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                                        items={[
                                            () => <IconTile icon={<ClockCountdown aria-hidden focusable="false" />} tone="warning" size="lg" />,
                                        ]} />
                                ),
                                () => (
                                    <StackV gap={2} principle="title-subtitle" align="center"
                                        explain="Title over supporting line — not label-field, because neither line is a form control label."
                                        items={[
                                            () => <h1 className="text-2xl font-bold">{t("payment.sepay.expired.title")}</h1>,
                                            () => <p className="text-muted">{t("payment.sepay.expired.description")}</p>,
                                        ]} />
                                ),
                                () => (
                                    <StackV gap={4} principle="content-row" classNames={["w-full"]}
                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                        items={[
                                            () => (
                                                <Button
                                                    variant="primary"
                                                    classNames={["w-full"]}
                                                    label={t("payment.sepay.expired.startOver")}
                                                    onPress={onStartOver}
                                                />
                                            ),
                                            () => (
                                                <Button
                                                    variant="secondary"
                                                    classNames={["w-full"]}
                                                    label={t("payment.sepay.expired.recheck")}
                                                    onPress={onRecheck}
                                                />
                                            ),
                                        ]} />
                                ),
                            ]} />
                    </Card.Content>
                </Box>
            </Card>
        </Box>
    )
}

"use client"

import React, {
    useCallback,
    useMemo,
} from "react"
import {
    Card,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    useSearchParams,
} from "next/navigation"
import type {
    BankDetails,
} from "../types"
import {
    parseBankDetails,
} from "../utils"
import {
    DetailRow,
} from "../DetailRow"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * Right-hand panel: the price card plus the bank/account/amount/content rows.
 *
 * Self-contained section (single-use): reads its own checkout query params,
 * derives the destination bank from the QR url, and owns the clipboard copy
 * handler — so the checkout container only renders `<OrderSummary />` and the
 * logic lives next to where it is used. `"use client"` for the query-params /
 * i18n hooks and the interactive copy rows. The repeated rows are rendered via
 * the presentational {@link DetailRow} (list-style), which takes the local
 * `onCopy` handler as a prop.
 */
export const OrderSummary = () => {
    const t = useTranslations()
    const searchParams = useSearchParams()

    const amount = searchParams.get("amount") || ""
    const referenceId = searchParams.get("ref") || ""
    const courseTitle = searchParams.get("courseTitle") || ""
    const qrUrl = searchParams.get("qr") || ""

    /** Destination bank + account parsed once from the QR url. */
    const bankDetails = useMemo<BankDetails>(
        () => parseBankDetails(qrUrl),
        [
            qrUrl,
        ],
    )

    /** Copy the given text to the clipboard. */
    const onCopy = useCallback(
        (text: string) => {
            void navigator.clipboard.writeText(text)
        },
        [],
    )

    return (
        <StackV identity={{ tier: "page", component: "OrderSummary" }} gap={6} principle="block-boundary"
            explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
            items={[
                () => (
                    <Card className="bg-default/40 backdrop-blur-md">
                        <Box principle="card-padding" className="p-6"
                            explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                            <Card.Content>
                                <h3 className="mb-4 text-lg font-medium">{courseTitle}</h3>
                                <StackH gap={3} principle="value-row" align="baseline"
                                    explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                                    items={[
                                        () => (
                                            <span className="text-3xl font-bold text-primary">
                                                {Number(amount).toLocaleString("vi-VN")}
                                            </span>
                                        ),
                                        () => <span className="text-sm text-muted">VND</span>,
                                    ]} />
                            </Card.Content>
                        </Box>
                    </Card>
                ),

                () => (
                    <Card className="flex-grow bg-default/40 backdrop-blur-md">
                        <Box principle="card-padding" className="p-6"
                            explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                            <Card.Content>
                                <StackV gap={4} principle="content-row"
                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                    items={[
                                        () => <DetailRow label={t("payment.sepay.bank")} value={bankDetails.bank} />,
                                        () => (
                                            <DetailRow
                                                copyValue={bankDetails.account}
                                                label={t("payment.sepay.account")}
                                                showCopy
                                                value={bankDetails.account}
                                                onCopy={onCopy}
                                            />
                                        ),
                                        () => (
                                            <DetailRow
                                                copyValue={amount}
                                                label={t("payment.sepay.amount")}
                                                showCopy
                                                value={`${Number(amount).toLocaleString("vi-VN")} VND`}
                                                onCopy={onCopy}
                                            />
                                        ),
                                        () => (
                                            <DetailRow
                                                copyValue={referenceId}
                                                isHighlighted
                                                label={t("payment.sepay.content")}
                                                showCopy
                                                value={referenceId}
                                                onCopy={onCopy}
                                            />
                                        ),
                                    ]} />
                            </Card.Content>
                        </Box>
                    </Card>
                ),
            ]} />
    )
}
